/* ---- Leadership Program page (editable from Appearance → Customize) ---- */
add_action( 'customize_register', function ( $wp_customize ) {
	$wp_customize->add_section( 'gc_leadership_program', array(
		'title'       => __( 'Leadership Program Page', 'game-changers' ),
		'description' => __( 'Edit the public Leadership Program (Leaders Cadres) page. Tier names & prices also come from Settings → Membership Tiers.', 'game-changers' ),
		'priority'    => 45,
	) );

	$fields = array(
		'gc_lp_hero_kicker'      => array( 'label' => 'Hero kicker', 'default' => 'Leaders Cadres', 'type' => 'text' ),
		'gc_lp_hero_title'       => array( 'label' => 'Hero title (use <br> and <em>)', 'default' => 'Game Changers<br><em>Leadership Program.</em>', 'type' => 'textarea' ),
		'gc_lp_hero_lead'        => array( 'label' => 'Hero lead paragraph', 'default' => 'Nigeria will rise — when her citizens rise. We engineer structured, value-driven leaders from the ground up.', 'type' => 'textarea' ),
		'gc_lp_hero_cta'         => array( 'label' => 'Hero primary button text', 'default' => 'Join Foundations Circle', 'type' => 'text' ),
		'gc_lp_challenge_kicker' => array( 'label' => 'Challenge section kicker', 'default' => 'The challenge', 'type' => 'text' ),
		'gc_lp_challenge_title'  => array( 'label' => 'Challenge title (use <br> and <em>)', 'default' => 'Nations do not fail for lack of resources.<br><em>They fail for lack of structured leadership.</em>', 'type' => 'textarea' ),
		'gc_lp_pathway_kicker'   => array( 'label' => 'Pathway kicker', 'default' => 'The pathway', 'type' => 'text' ),
		'gc_lp_pathway_title'    => array( 'label' => 'Pathway title (use <br> and <em>)', 'default' => '5 Levels. One Mission.<br><em>National Transformation.</em>', 'type' => 'textarea' ),
		'gc_lp_pathway_intro'    => array( 'label' => 'Pathway intro', 'default' => "You don't join randomly. You grow intentionally. Promotion is earned through participation, module completion, ethical conduct, demonstrated impact, and referral of serious members.", 'type' => 'textarea' ),
		'gc_lp_cta_kicker'       => array( 'label' => 'Final CTA kicker', 'default' => 'The question is not “Will Nigeria change?”', 'type' => 'text' ),
		'gc_lp_cta_title'        => array( 'label' => 'Final CTA title (use <em>)', 'default' => 'Will you be among those who <em>shaped the change?</em>', 'type' => 'textarea' ),
		'gc_lp_cta_body'         => array( 'label' => 'Final CTA body', 'default' => 'Join the Foundations Circle. Begin your structured leadership journey. Become a Game Changer.', 'type' => 'textarea' ),
		'gc_lp_cta_button'       => array( 'label' => 'Final CTA button text', 'default' => 'Join Foundations Circle — ₦5,000', 'type' => 'text' ),
	);

	foreach ( $fields as $id => $cfg ) {
		$wp_customize->add_setting( $id, array(
			'default'           => $cfg['default'],
			'sanitize_callback' => ( 'textarea' === $cfg['type'] ) ? 'wp_kses_post' : 'sanitize_text_field',
		) );
		$wp_customize->add_control( $id, array(
			'label'   => $cfg['label'],
			'section' => 'gc_leadership_program',
			'type'    => $cfg['type'],
		) );
	}
} );
